export type ViewT = { zoom: number; panX: number; panY: number; split: number };
export type AreaT = { x: number; y: number; width: number; height: number };
export type ImageRectT = AreaT & { scale: number };
export type SizeT = { width: number; height: number };
export type DividerT = { x: number; top: number; height: number; visible: boolean };
